36: /*!
37:  * LOG4QT_DECLARE_STATIC_LOGGER declares a static function \a FUNCTION that
38:  * returns a pointer to a \ref Log4Qt::Logger "Logger" named after \a CLASS.
39:  *
40:  * On the first invocation the \ref Log4Qt::Logger "Logger" is requested
41:  * by calling \ref Log4Qt::Logger::logger(const char *pName)
42:  * "Logger::logger( #CLASS )". The pointer is stored to be returned on
43:  * subsequent invocations.
44:  *
45:  * The following example shows how to use the macro to define a logger to be
46:  * used within a class not derived from QObject.
47:  *
48:  * \code
49:  * #file: counter.h
50:  *
51:  * #include logger.h
52:  *
53:  * class Counter
54:  * {
55:  * public:
56:  *     Counter();
57:  *     Counter(int preset);
58:  * private:
59:  *     int mCount;
60:  * }
61:  * \endcode
62:  * \code
63:  * #file: counter.cpp
64:  *
65:  * #include counter.h
66:  *
67:  * LOG4QT_DECLARE_STATIC_LOGGER(logger, Counter)
68:  *
69:  * Counter::Counter() :
70:  *     mCount(0)
71:  * {}
72:  *
73:  * void Counter::Counter(int preset) :
74:  *     mCount(preset)
75:  * {
76:  *     if (preset < 0)
77:  *     {
78:  *         logger()->warn("Invalid negative counter preset %1. Using 0 instead.", preset);
79:  *         mCount = 0;
80:  *     }
81:  * }
82:  * \endcode
83:  *
84:  * \note The function created by the macro is thread-safe.
85:  *
86:  * \sa \ref Log4Qt::Logger::logger(const char *pName) "Logger::logger(const char *pName)"
87:  */
88: #define LOG4QT_DECLARE_STATIC_LOGGER(FUNCTION, CLASS)                     \
89:         static Log4Qt::Logger *FUNCTION()                                 \
90:         {                                                                 \
91:             static Log4Qt::Logger * p_logger(Log4Qt::Logger::logger(#CLASS )); \
92:             return p_logger;                                               \
93:         }
94: 
95: /*!
96:  * LOG4QT_DECLARE_QCLASS_LOGGER declares member functions to retrieve
97:  * \ref Log4Qt::Logger "Logger" for the class it is used in.
98:  *
99:  * On the first invocation the \ref Log4Qt::Logger "Logger" is requested
100:  * by a call to \ref Log4Qt::Logger::logger(const char *pName)
101:  * "Logger::logger(const char *pName)". The pointer is stored to be
102:  * returned on subsequent invocations.
103:  *
104:  * The following example shows how to use the macro to define a logger to be
105:  * used within a class derived from QObject.
106:  *
107:  * \code
108:  * #file: counter.h
109:  *
110:  * #include qobject.h
111:  * #include logger.h
112:  *
113:  * class Counter : public QObject
114:  * {
115:  *     Q_OBJECT
116:  *     LOG4QT_DECLARE_QCLASS_LOGGER
117:  * public:
118:  *     Counter();
119:  *     Counter(int preset);
120:  * private:
121:  *     int mCount;
122:  * }
123:  * \endcode
124:  * \code
125:  * #file: counter.cpp
126:  *
127:  * #include counter.h
128:  *
129:  * Counter::Counter() :
130:  *     mCount(0)
131:  * {}
132:  *
133:  * void Counter::Counter(int preset)
134:  *     mCount(preset)
135:  * {
136:  *     if (preset < 0)
137:  *     {
138:  *         logger()->warn("Invalid negative counter preset %1. Using 0 instead.", preset);
139:  *         mCount = 0;
140:  *     }
141:  * }
142:  * \endcode
143:  *
144:  * \note The function created by the macro is thread-safe.
145:  *
146:  * \sa \ref Log4Qt::Logger::logger(const char *pName) "Logger::logger(const char *pName)",
147:  *     \ref Log4Qt::ClassLogger "ClassLogger"
148:  */
149: #define LOG4QT_DECLARE_QCLASS_LOGGER                                      \
150:             private:                                                              \
151:                     mutable Log4Qt::ClassLogger mLog4QtClassLogger;                   \
152:             public:                                                               \
153:                     Log4Qt::Logger *logger() const                             \
154:                     {   return mLog4QtClassLogger.logger(this);    }                  \
155:             private:
156: 
157: 
158: class LOG4QT_EXPORT MessageLogger
159: {
160:     Q_DISABLE_COPY_MOVE(MessageLogger)
161: 
162: public:
163:     explicit MessageLogger(Logger *logger, Level level) : mLogger(logger), mLevel(level) {}
164:     explicit MessageLogger(Logger *logger, Level level, const char *file, int line, const char *function)
165:         : mLogger(logger), mLevel(level), mContext(file, line, function) {}
166: #ifdef __cpp_lib_source_location
167:     explicit MessageLogger(Logger *logger, Level level, const std::source_location &loc)
168:         : mLogger(logger), mLevel(level), mContext(loc) {}
169: #endif
170: 
171:     void log(const QString &message) const;
172:     template <typename ...Ts>
173:     void log(const QString &message, Ts &&...ts) const
174:     {
175:         auto msg = message;
176:         ((msg = msg.arg(std::forward<Ts>(ts))), ...);
177:         log(msg);
178:     }
179:     LogStream log() const;
180: 
181: private:
182:     QPointer<const Logger> mLogger;
183:     Level mLevel;
184:     MessageContext mContext;
185: };
