197: #define l4qInfo(...) \
198:     for (Log4Qt::Logger *l4q_p_logger = logger(); l4q_p_logger && l4q_p_logger->isEnabledFor(Log4Qt::Level::INFO_INT); l4q_p_logger = nullptr) \
