210: /*!
211:  * \brief The class Logger provides logging services.
212:  *
213:  * A pointer to a logger can be retrieved by calling Logger::logger() or
214:  * LogManager::logger() with the class name as argument. Because a logger
215:  * is never destroyed it is possible to store the pointer to the logger.
216:  * This way the lookup of the pointer in the repository is only required
217:  * on the first logging operation. The macros \ref
218:  * Log4Qt::LOG4QT_DECLARE_STATIC_LOGGER "LOG4QT_DECLARE_STATIC_LOGGER" and
219:  * \ref Log4Qt::LOG4QT_DECLARE_QCLASS_LOGGER "LOG4QT_DECLARE_QCLASS_LOGGER"
220:  * provide a thread-safe implementation to store the logger pointer.
221:  *
222:  * \note All the functions declared in this class are thread-safe.
223:  */
224: class LOG4QT_EXPORT Logger : public QObject, public AppenderAttachable
225: {
226:     Q_OBJECT
227: 
228:     /*!
229:      * The property holds, if the logger is additive.
230:      *
231:      * The default is true for being additive.
232:      *
233:      * \sa additive(), setAdditive()
234:      */
235:     Q_PROPERTY(bool additivity READ additivity WRITE setAdditivity)
