/*!
 * LOG4QT_DECLARE_STATIC_LOGGER declares a static function \a FUNCTION that
 * returns a pointer to a \ref Log4Qt::Logger "Logger" named after \a CLASS.
 *
 * On the first invocation the \ref Log4Qt::Logger "Logger" is requested
 * by calling \ref Log4Qt::Logger::logger(const char *pName)
 * "Logger::logger( #CLASS )". The pointer is stored to be returned on
 * subsequent invocations.
 *
 * The following example shows how to use the macro to define a logger to be
 * used within a class not derived from QObject.
 *
 * \code
 * #file: counter.h
 *
 * #include logger.h
 *
 * class Counter
 * {
 * public:
 *     Counter();
 *     Counter(int preset);
 * private:
 *     int mCount;
 * }
 * \endcode
 * \code
 * #file: counter.cpp
 *
 * #include counter.h
 *
 * LOG4QT_DECLARE_STATIC_LOGGER(logger, Counter)
 *
 * Counter::Counter() :
 *     mCount(0)
 * {}
 *
 * void Counter::Counter(int preset) :
 *     mCount(preset)
 * {
 *     if (preset < 0)
 *     {
 *         logger()->warn("Invalid negative counter preset %1. Using 0 instead.", preset);
 *         mCount = 0;
 *     }
 * }
 * \endcode
 *
 * \note The function created by the macro is thread-safe.
 *
 * \sa \ref Log4Qt::Logger::logger(const char *pName) "Logger::logger(const char *pName)"
 */
#define LOG4QT_DECLARE_STATIC_LOGGER(FUNCTION, CLASS)                     \
        static Log4Qt::Logger *FUNCTION()                                 \
        {                                                                 \
            static Log4Qt::Logger * p_logger(Log4Qt::Logger::logger(#CLASS )); \
            return p_logger;                                               \
        }

/*!
 * LOG4QT_DECLARE_QCLASS_LOGGER declares member functions to retrieve
 * \ref Log4Qt::Logger "Logger" for the class it is used in.
 *
 * On the first invocation the \ref Log4Qt::Logger "Logger" is requested
 * by a call to \ref Log4Qt::Logger::logger(const char *pName)
 * "Logger::logger(const char *pName)". The pointer is stored to be
 * returned on subsequent invocations.
 *
 * The following example shows how to use the macro to define a logger to be
 * used within a class derived from QObject.
 *
 * \code
 * #file: counter.h
 *
 * #include qobject.h
 * #include logger.h
 *
 * class Counter : public QObject
 * {
 *     Q_OBJECT
 *     LOG4QT_DECLARE_QCLASS_LOGGER
 * public:
 *     Counter();
 *     Counter(int preset);
 * private:
 *     int mCount;
 * }
 * \endcode
 * \code
 * #file: counter.cpp
 *
 * #include counter.h
 *
 * Counter::Counter() :
 *     mCount(0)
 * {}
 *
 * void Counter::Counter(int preset)
 *     mCount(preset)
 * {
 *     if (preset < 0)
 *     {
 *         logger()->warn("Invalid negative counter preset %1. Using 0 instead.", preset);
 *         mCount = 0;
 *     }
 * }
 * \endcode
 *
 * \note The function created by the macro is thread-safe.
 *
 * \sa \ref Log4Qt::Logger::logger(const char *pName) "Logger::logger(const char *pName)",
 *     \ref Log4Qt::ClassLogger "ClassLogger"
 */
#define LOG4QT_DECLARE_QCLASS_LOGGER                                      \
            private:                                                              \
                    mutable Log4Qt::ClassLogger mLog4QtClassLogger;                   \
            public:                                                               \
                    Log4Qt::Logger *logger() const                             \
                    {   return mLog4QtClassLogger.logger(this);    }                  \
            private:


class LOG4QT_EXPORT MessageLogger
{
    Q_DISABLE_COPY_MOVE(MessageLogger)

public:
    explicit MessageLogger(Logger *logger, Level level) : mLogger(logger), mLevel(level) {}
    explicit MessageLogger(Logger *logger, Level level, const char *file, int line, const char *function)
        : mLogger(logger), mLevel(level), mContext(file, line, function) {}
#ifdef __cpp_lib_source_location
    explicit MessageLogger(Logger *logger, Level level, const std::source_location &loc)
        : mLogger(logger), mLevel(level), mContext(loc) {}
#endif

    void log(const QString &message) const;
    template <typename ...Ts>
    void log(const QString &message, Ts &&...ts) const
    {
        auto msg = message;
        ((msg = msg.arg(std::forward<Ts>(ts))), ...);
        log(msg);
    }
    LogStream log() const;

private:
    QPointer<const Logger> mLogger;
    Level mLevel;
    MessageContext mContext;
};

// Macros to log with location information, the logger must have the name
#define l4qFatal(...) \
    for (Log4Qt::Logger *l4q_p_logger = logger(); l4q_p_logger && l4q_p_logger->isEnabledFor(Log4Qt::Level::FATAL_INT); l4q_p_logger = nullptr) \
        Log4Qt::MessageLogger(l4q_p_logger, Log4Qt::Level::FATAL_INT, __FILE__, __LINE__, Q_FUNC_INFO).log(__VA_ARGS__)
#define l4qError(...) \
    for (Log4Qt::Logger *l4q_p_logger = logger(); l4q_p_logger && l4q_p_logger->isEnabledFor(Log4Qt::Level::ERROR_INT); l4q_p_logger = nullptr) \
        Log4Qt::MessageLogger(l4q_p_logger, Log4Qt::Level::ERROR_INT, __FILE__, __LINE__, Q_FUNC_INFO).log(__VA_ARGS__)
#define l4qWarn(...) \
    for (Log4Qt::Logger *l4q_p_logger = logger(); l4q_p_logger && l4q_p_logger->isEnabledFor(Log4Qt::Level::WARN_INT); l4q_p_logger = nullptr) \
        Log4Qt::MessageLogger(l4q_p_logger, Log4Qt::Level::WARN_INT, __FILE__, __LINE__, Q_FUNC_INFO).log(__VA_ARGS__)
#define l4qInfo(...) \
    for (Log4Qt::Logger *l4q_p_logger = logger(); l4q_p_logger && l4q_p_logger->isEnabledFor(Log4Qt::Level::INFO_INT); l4q_p_logger = nullptr) \
        Log4Qt::MessageLogger(l4q_p_logger, Log4Qt::Level::INFO_INT, __FILE__, __LINE__, Q_FUNC_INFO).log(__VA_ARGS__)
#define l4qDebug(...) \
