104:     DWORD out;
105: 
106:     QString parsedWordString;
107:     QStringList escParams;
108:     int indexOfM;
109:     // display first part of message
110:     if (!colorizedMessage.at(0).isEmpty())
111:     {
112:         std::vector<wchar_t> wideBuf(colorizedMessage.at(0).size());
113:         actualSize = colorizedMessage.at(0).toWCharArray(wideBuf.data());
114:         WriteConsoleW(hConsole, wideBuf.data(), actualSize, &out, nullptr);
115:         colorizedMessage.removeAt(0);
116:     }
117:     for (QString it : colorizedMessage)
118:     {
119:         // color setted
120:         if (it.startsWith('['))
121:         {
122:             indexOfM = it.indexOf('m');
